[Fact]
public void AC1_ClosedFormatterSwitchHasNoTrailingSemicolon()
{
    var (trees, _) = Generate(ClosedFormattersSource);
    MethodDeclarationSyntax getFormatter = FindGetFormatter(trees);

    var switches = getFormatter.DescendantNodes().OfType<SwitchStatementSyntax>().ToList();
    Assert.NotEmpty(switches);
    foreach (var sw in switches)
    {
        AssertNoEmptyStatementAfter(sw);
    }

    string text = getFormatter.ToFullString();
    Assert.DoesNotMatch(@"default: return null;[^\r\n]*\r?\n\s*\}

[Fact]
public void AC2_ClosedSwitchHasOneCasePerLookupEntryPlusDefault()
{
    var (trees, _) = Generate(ClosedFormattersSource);
    MethodDeclarationSyntax getFormatter = FindGetFormatter(trees);
    var helper = (ClassDeclarationSyntax)getFormatter.Parent!;

    var closedLookup = helper.Members.OfType<FieldDeclarationSyntax>()
        .Single(f => f.Declaration.Variables.Any(v => v.Identifier.Text == "closedTypeLookup"));
    var initializer = closedLookup.Declaration.Variables.Single().Initializer!.Value
        .DescendantNodes().OfType<InitializerExpressionSyntax>().First();
    var entries = initializer.Expressions.OfType<InitializerExpressionSyntax>().ToList();
    Assert.True(entries.Count >= 2);

    var sw = getFormatter.DescendantNodes().OfType<SwitchStatementSyntax>()
        .Single(s => s.Expression.ToString() == "closedKey");

    var caseSections = sw.Sections.Where(s => s.Labels.OfType<CaseSwitchLabelSyntax>().Any()).ToList();
    Assert.Equal(entries.Count, caseSections.Count);

    // Each lookup entry's index maps to a case that returns a new formatter instance.
    foreach (var entry in entries)
    {
        string index = entry.Expressions[1].ToString();
        var section = caseSections.Single(s => s.Labels.OfType<CaseSwitchLabelSyntax>().Single().Value.ToString() == index);
        var ret = Assert.IsType<ReturnStatementSyntax>(section.Statements.Single());
        Assert.IsType<ObjectCreationExpressionSyntax>(ret.Expression);
    }

    // The two custom formatters are each constructed for their data type.
    string swText = sw.ToString();
    Assert.Contains("new global::Probe.SomeTypeNameFormatter()", swText);
    Assert.Contains("new global::Probe.OtherTypeNameFormatter()", swText);

    var defaultSection = sw.Sections.Single(s => s.Labels.OfType<DefaultSwitchLabelSyntax>().Any());
    var defRet = Assert.IsType<ReturnStatementSyntax>(defaultSection.Statements.Single());
    Assert.Equal("null", defRet.Expression!.ToString());
}

[Fact]
public void AC3_BothClosedAndOpenGenericSwitchesHaveNoTrailingEmptyStatement()
{
    var (trees, _) = Generate(ClosedFormattersSource, OpenGenericFormatterSource);
    MethodDeclarationSyntax getFormatter = FindGetFormatter(trees);

    var switches = getFormatter.DescendantNodes().OfType<SwitchStatementSyntax>().ToList();
    Assert.Contains(switches, s => s.Expression.ToString() == "closedKey");
    Assert.Contains(switches, s => s.Expression.ToString() == "openKey");

    foreach (var tree in trees)
    {
        foreach (var sw in tree.GetRoot().DescendantNodes().OfType<SwitchStatementSyntax>())
        {
            AssertNoEmptyStatementAfter(sw);
        }
    }
}

[Fact]
public void AC4_GeneratedResolverCompilesWithoutErrorsOrWarnings()
{
    var (trees, compilation) = Generate(ClosedFormattersSource, OpenGenericFormatterSource);
    var generatedPaths = new HashSet<string>(trees.Select(t => t.FilePath));
    var problems = compilation.GetDiagnostics()
        .Where(d => d.Severity >= DiagnosticSeverity.Warning)
        .Where(d => d.Location.SourceTree is null || generatedPaths.Contains(d.Location.SourceTree.FilePath))
        .ToList();
    Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems));
}

[Fact]
public void AC6_NoCustomFormattersGeneratesCompilableResolver()
{
    var (trees, compilation) = Generate(NoCustomFormatterSource);
    Assert.NotEmpty(trees);
    var generatedPaths = new HashSet<string>(trees.Select(t => t.FilePath));
    var errors = compilation.GetDiagnostics()
        .Where(d => d.Severity == DiagnosticSeverity.Error)
        .Where(d => d.Location.SourceTree is null || generatedPaths.Contains(d.Location.SourceTree.FilePath))
        .ToList();
    Assert.True(errors.Count == 0, string.Join(Environment.NewLine, errors));

    MethodDeclarationSyntax getFormatter = FindGetFormatter(trees);

    // No custom/open-generic formatters: no open-type lookup switch, and method falls through to return null.
    Assert.DoesNotContain(getFormatter.DescendantNodes().OfType<SwitchStatementSyntax>(), s => s.Expression.ToString() == "openKey");
    var last = Assert.IsType<ReturnStatementSyntax>(getFormatter.Body!.Statements.Last());
    Assert.Equal("null", last.Expression!.ToString());
}
